// Test generators (design §11): `header-tests` and `layout-tests`, from a
// stela.model/1. Generated files are plain C and C++; the project's build
// compiles them with warnings as errors.

import path from "node:path";
import { StelaError } from "./errors.ts";
import type { Declaration, Model, ModelLibrary } from "./model.ts";

export interface GeneratedFile {
  /** Relative to the output directory, with `/` separators. */
  readonly path: string;
  readonly text: string;
}

/**
 * Each target's predefined-macro guard. ARM64EC also defines `_M_X64`, which
 * is why the x64 guard excludes it.
 */
export const TARGET_GUARDS: Readonly<Record<string, string>> = {
  "x86_64-pc-windows-msvc": "defined(_M_X64) && !defined(_M_ARM64EC)",
  "i686-pc-windows-msvc": "defined(_M_IX86)",
  "aarch64-pc-windows-msvc": "defined(_M_ARM64)",
  "arm64ec-pc-windows-msvc": "defined(_M_ARM64EC)",
};

export const GENERATORS = ["header-tests", "layout-tests"] as const;
export type GeneratorName = (typeof GENERATORS)[number];

const IDENTIFIER_RE = /^[A-Za-z_][A-Za-z0-9_]*$/;

function guard(target: string): string {
  const g = TARGET_GUARDS[target];
  if (g === undefined) throw new StelaError(`no predefined-macro guard is known for target ${target}`);
  return g;
}

function libraryTargets(model: Model, library: ModelLibrary): string[] {
  return library.targets ?? model.targets;
}

/** The header as a consumer includes it: relative to the first include directory that holds it. */
export function includeSpelling(library: ModelLibrary, header: string): string {
  for (const dir of library.includeDirs) {
    if (header.startsWith(`${dir}/`)) return header.slice(dir.length + 1);
  }
  throw new StelaError(`${library.name}: no include directory holds ${header}`);
}

function banner(generator: GeneratorName, lines: readonly string[]): string {
  return [
    `/* Generated by Stela (${generator}) from a stela.model/1 model. Do not edit.`,
    ...lines.map((l) => ` * ${l}`.trimEnd()),
    " */",
    "",
  ].join("\n");
}

function defines(library: ModelLibrary): string[] {
  return library.defines.map((d) => {
    const eq = d.indexOf("=");
    return eq < 0 ? `#define ${d}` : `#define ${d.slice(0, eq)} ${d.slice(eq + 1)}`;
  });
}

function stem(header: string): string {
  return path.posix.basename(header).replace(/\.[^.]*$/, "");
}

/**
 * One C and one C++ file per entry header, and per generated stela header;
 * each includes only that header.
 */
export function generateHeaderTests(model: Model): GeneratedFile[] {
  const files: GeneratedFile[] = [];
  for (const library of model.libraries) {
    const headers = library.stelaHeader === undefined ? library.headers : [...library.headers, library.stelaHeader];
    for (const header of headers) {
      const include = includeSpelling(library, header);
      const text = [
        banner("header-tests", [
          `${include} must compile on its own. It's included twice to check its`,
          "include guard.",
        ]),
        ...defines(library),
        `#include "${include}"`,
        `#include "${include}"`,
        "",
        "/* Keeps the translation unit from being empty in pedantic C. */",
        "typedef int stela_header_test_unit;",
        "",
      ].join("\n");
      for (const ext of ["c", "cpp"]) {
        files.push({ path: `${library.name}/${stem(header)}.header.${ext}`, text });
      }
    }
  }
  return files;
}

interface Lang {
  readonly assert: string;
  readonly alignof: string;
}

const C: Lang = { assert: "_Static_assert", alignof: "_Alignof" };
const CPP: Lang = { assert: "static_assert", alignof: "alignof" };

function assertLine(lang: Lang, condition: string, message: string): string {
  return `${lang.assert}(${condition}, "${message}");`;
}

/** Whether a type node, or the canonical type it names, is a function type. */
function isFunctionType(decl: Declaration, target: string): boolean {
  const canonical = decl.perTarget?.[target]?.canonicalType;
  return (canonical !== undefined && "function" in canonical) || (decl.type !== undefined && "function" in decl.type);
}

function recordName(decl: Declaration): string | undefined {
  if (!IDENTIFIER_RE.test(decl.name)) return undefined;
  // A tag-less record is spelled by the typedef that names it.
  return decl.tagless ? decl.name : `${decl.kind} ${decl.name}`;
}

function layoutChecks(lang: Lang, decls: readonly Declaration[], target: string): string[] {
  const lines: string[] = [];
  for (const decl of decls) {
    if (decl.targets !== undefined && !decl.targets.includes(target)) continue;
    const facts = decl.perTarget?.[target];
    if (facts === undefined) continue;
    if ((decl.kind === "struct" || decl.kind === "union") && !decl.incomplete) {
      const type = recordName(decl);
      if (type === undefined || facts.size === undefined) continue;
      lines.push(assertLine(lang, `sizeof(${type}) == ${facts.size}`, `size of ${type} on ${target}`));
      lines.push(assertLine(lang, `${lang.alignof}(${type}) == ${facts.align}`, `alignment of ${type} on ${target}`));
      (decl.fields ?? []).forEach((field, i) => {
        const offset = facts.offsets?.[i];
        // offsetof can't name a bit-field or an anonymous member.
        if (field.bitWidth !== undefined || !IDENTIFIER_RE.test(field.name)) return;
        if (offset === undefined || offset < 0) return;
        lines.push(
          assertLine(
            lang,
            `offsetof(${type}, ${field.name}) == ${offset}`,
            `offset of ${type}.${field.name} on ${target}`,
          ),
        );
      });
    } else if (decl.kind === "typedef") {
      if (facts.size === undefined || facts.size <= 0 || isFunctionType(decl, target)) continue;
      lines.push(assertLine(lang, `sizeof(${decl.name}) == ${facts.size}`, `size of ${decl.name} on ${target}`));
      lines.push(
        assertLine(lang, `${lang.alignof}(${decl.name}) == ${facts.align}`, `alignment of ${decl.name} on ${target}`),
      );
    }
  }
  return lines;
}

function enumeratorChecks(lang: Lang, model: Model, library: ModelLibrary): string[] {
  const all = libraryTargets(model, library);
  const lines: string[] = [];
  for (const decl of library.declarations) {
    if (decl.kind !== "enum" || !decl.enumerators?.length) continue;
    const checks = decl.enumerators.map((e) =>
      assertLine(lang, `(long long)(${e.name}) == ${e.value}LL`, `value of ${e.name}`),
    );
    if (decl.targets === undefined || decl.targets.length === all.length) {
      lines.push(...checks);
    } else {
      lines.push(`#if ${decl.targets.map((t) => `(${guard(t)})`).join(" || ")}`, ...checks, "#endif");
    }
  }
  return lines;
}

function layoutFile(lang: Lang, model: Model, library: ModelLibrary): string {
  const targets = libraryTargets(model, library);
  const guards = targets.map((t) => `!(${guard(t)})`).join(" && ");
  const out = [
    banner("layout-tests", [
      `Library ${library.name}: sizes, alignments, field offsets, and enumerator`,
      `values, as Clang computed them for ${targets.join(", ")}.`,
    ]),
    ...defines(library),
    ...library.headers.map((h) => `#include "${includeSpelling(library, h)}"`),
    "",
    "#include <stddef.h>",
    "",
    `#if ${guards}`,
    `#error "stela: the model of ${library.name} has no layout for this target"`,
    "#endif",
  ];
  const enumerators = enumeratorChecks(lang, model, library);
  if (enumerators.length > 0) out.push("", "/* Enumerator values (every target). */", ...enumerators);
  for (const target of targets) {
    const checks = layoutChecks(lang, library.declarations, target);
    if (checks.length === 0) continue;
    out.push("", `#if ${guard(target)} /* ${target} */`, ...checks, "#endif");
  }
  out.push("");
  return out.join("\n");
}

/** A C11 and a C++ file per library, with static assertions guarded per target. */
export function generateLayoutTests(model: Model): GeneratedFile[] {
  return model.libraries.flatMap((library) => [
    { path: `${library.name}/layout.c`, text: layoutFile(C, model, library) },
    { path: `${library.name}/layout.cpp`, text: layoutFile(CPP, model, library) },
  ]);
}

export function generate(name: string, model: Model): GeneratedFile[] {
  switch (name) {
    case "header-tests":
      return generateHeaderTests(model);
    case "layout-tests":
      return generateLayoutTests(model);
    default:
      throw new StelaError(`unknown generator "${name}"; known: ${GENERATORS.join(", ")}`);
  }
}
